import 'dart:async';
import 'package:flutter/material.dart';
import '../core/api_client.dart';
import 'offline_sale_queue.dart';

class PosScreen extends StatefulWidget { const PosScreen({super.key, required this.api}); final PosApiClient api; @override State<PosScreen> createState()=>_PosScreenState(); }
class _PosScreenState extends State<PosScreen> {
 final _barcode=TextEditingController(),_search=TextEditingController(); final _cart=<int,_CartLine>{}; final _queue=OfflineSaleQueue(); Timer? _retryTimer;
 List<Map<String,dynamic>> _products=[],_tables=[]; String _orderType='Dine In',_payment='Cash',_status=''; int? _tableId,_pendingCount; bool _loading=true,_saving=false,_syncing=false;
 @override void initState(){super.initState();_loadCatalog();_refreshQueue();_retryTimer=Timer.periodic(const Duration(seconds:30),(_)=>_syncQueue(silent:true));}
 Future<void> _loadCatalog()async{try{final p=await widget.api.products(),t=await widget.api.tables();if(!mounted)return;setState((){_products=p.whereType<Map<String,dynamic>>().where((x)=>x['available']==true).toList();_tables=t.whereType<Map<String,dynamic>>().where((x)=>x['active']==true&&x['status']=='Available').toList();_loading=false;});}catch(_){if(mounted)setState(()=>_loading=false);}}
 Future<void> _refreshQueue()async{final n=await _queue.count();if(mounted)setState(()=>_pendingCount=n);}
 Future<void> _syncQueue({bool silent=false})async{if(_syncing)return;if(await _queue.count()==0){if(!silent&&mounted)setState(()=>_status='No pending offline sales.');return;}if(mounted)setState(()=>_syncing=true);try{final r=await _queue.sync(widget.api);if(!mounted)return;setState(()=>_pendingCount=r.pending);if(!silent)setState(()=>_status='Synced ${r.completed}; ${r.conflicts} conflict(s); ${r.pending} pending.');}catch(_){if(!silent&&mounted)setState(()=>_status='Sync unavailable; sales remain queued.');}finally{if(mounted)setState(()=>_syncing=false);}}
 void _add(Map<String,dynamic> p){final id=(p['id'] as num).toInt(),name='${p['name']??''}',price=(p['price'] as num).toDouble();setState((){final l=_cart[id];_cart[id]=_CartLine(id,name,price,(l?.quantity??0)+1);_status='$name added';});}
 void _scan(){final c=_barcode.text.trim();if(c.isEmpty)return;final m=_products.where((p)=>'${p['barcode']??''}'==c).firstOrNull;if(m==null)setState(()=>_status='Barcode not found: $c');else{_add(m);_barcode.clear();}}
 double get _subtotal=>_cart.values.fold(0,(s,x)=>s+x.price*x.quantity);
 Future<void> _completeSale()async{if(_cart.isEmpty||_saving)return;if(_orderType=='Dine In'&&_tableId==null){setState(()=>_status='Select a table for Dine In');return;}setState(()=>_saving=true);final opId='pos-${DateTime.now().toUtc().microsecondsSinceEpoch}';final sale=<String,dynamic>{'clientOperationId':opId,'tableId':_orderType=='Dine In'?_tableId:null,'orderType':_orderType,'notes':'','items':_cart.values.map((x)=>{'productId':x.id,'quantity':x.quantity,'notes':''}).toList(),'paymentMethod':_payment,'amountTendered':_subtotal,'paymentReference':''};try{final order=await widget.api.createStaffOrder(tableId:sale['tableId'] as int?,orderType:_orderType,clientOperationId:opId,items:List<Map<String,dynamic>>.from(sale['items'] as List));final id=(order['id'] as num).toInt(),total=(order['total'] as num?)?.toDouble()??_subtotal;await widget.api.collectPayment(id,amountTendered:total,method:_payment);if(!mounted)return;setState((){_cart.clear();_tableId=null;_saving=false;_status='Sale #$id completed';});await _refreshQueue();await _loadCatalog();}catch(_){await _queue.enqueue(sale);await _refreshQueue();if(!mounted)return;setState((){_cart.clear();_tableId=null;_saving=false;_status='Offline: sale queued. $_pendingCount pending.';});}}
 @override void dispose(){_retryTimer?.cancel();_barcode.dispose();_search.dispose();super.dispose();}
 @override Widget build(BuildContext context){final q=_search.text.toLowerCase(),ps=_products.where((p)=>'${p['name']??''}'.toLowerCase().contains(q)||'${p['barcode']??''}'.contains(q));return Scaffold(appBar:AppBar(title:const Text('FindUpTo POS — Counter'),actions:[if((_pendingCount??0)>0)Padding(padding:const EdgeInsets.symmetric(horizontal:8),child:Center(child:Text('$_pendingCount pending'))),IconButton(onPressed:_syncing?null:()=>_syncQueue(),icon:const Icon(Icons.sync)),IconButton(onPressed:_loadCatalog,icon:const Icon(Icons.refresh))]),body:_loading?const Center(child:CircularProgressIndicator()):Row(children:[Expanded(flex:3,child:Padding(padding:const EdgeInsets.all(16),child:Column(children:[TextField(controller:_search,onChanged:(_)=>setState((){}),decoration:const InputDecoration(prefixIcon:Icon(Icons.search),labelText:'Search products',border:OutlineInputBorder())),const SizedBox(height:12),TextField(controller:_barcode,onSubmitted:(_)=>_scan(),decoration:const InputDecoration(prefixIcon:Icon(Icons.qrCodeScanner),labelText:'Scan / enter barcode',border:OutlineInputBorder())),const SizedBox(height:16),Expanded(child:ps.isEmpty?const Center(child:Text('No products found')):GridView.count(crossAxisCount:3,childAspectRatio:1.35,crossAxisSpacing:10,mainAxisSpacing:10,children:[for(final p in ps)Card(child:InkWell(onTap:()=>_add(p),child:Center(child:Column(mainAxisSize:MainAxisSize.min,children:[Text('${p['name']}',style:Theme.of(context).textTheme.titleMedium),const SizedBox(height:6),Text('Rs. ${((p['price'] as num).toDouble()).toStringAsFixed(0)}')]))))]))]))),const VerticalDivider(width:1),Expanded(flex:2,child:Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[Text('Current Sale',style:Theme.of(context).textTheme.headlineSmall),const SizedBox(height:8),Expanded(child:_cart.isEmpty?const Center(child:Text('Scan or select products')):ListView(children:[for(final l in _cart.values)ListTile(title:Text(l.name),subtitle:Text('Rs. ${l.price.toStringAsFixed(0)} × ${l.quantity}'),trailing:Row(mainAxisSize:MainAxisSize.min,children:[IconButton(onPressed:()=>setState((){if(l.quantity>1)l.quantity--;else _cart.remove(l.id);}),icon:const Icon(Icons.remove)),IconButton(onPressed:()=>_add(_products.firstWhere((p)=>(p['id'] as num).toInt()==l.id)),icon:const Icon(Icons.add))]))])),DropdownButtonFormField<String>(value:_orderType,items:const ['Dine In','Takeaway','Delivery'].map((x)=>DropdownMenuItem(value:x,child:Text(x))).toList(),onChanged:(x)=>setState((){_orderType=x!;if(_orderType!='Dine In')_tableId=null;}),decoration:const InputDecoration(labelText:'Order type')),if(_orderType=='Dine In')DropdownButtonFormField<int>(value:_tableId,items:_tables.map((t)=>DropdownMenuItem(value:(t['id'] as num).toInt(),child:Text('${t['name']}'))).toList(),onChanged:(x)=>setState(()=>_tableId=x),decoration:const InputDecoration(labelText:'Table')),DropdownButtonFormField<String>(value:_payment,items:const ['Cash','Card','Online'].map((x)=>DropdownMenuItem(value:x,child:Text(x))).toList(),onChanged:(x)=>setState(()=>_payment=x!),decoration:const InputDecoration(labelText:'Payment')),const SizedBox(height:12),Text('Subtotal: Rs. ${_subtotal.toStringAsFixed(2)}'),Text('TOTAL: Rs. ${_subtotal.toStringAsFixed(2)}',style:Theme.of(context).textTheme.titleLarge),const SizedBox(height:12),FilledButton.icon(onPressed:_saving?null:_completeSale,icon:const Icon(Icons.point_of_sale),label:Text(_saving?'Processing...':'Complete Sale')),if(_status.isNotEmpty)Padding(padding:const EdgeInsets.only(top:8),child:Text(_status))])))]));}
}
class _CartLine{_CartLine(this.id,this.name,this.price,this.quantity);final int id;final String name;final double price;int quantity;}
